```latex
\documentclass{article}
\usepackage{ctex} % 支持中文
\usepackage{pgfplots}
\pgfplotsset{compat=1.18} % 设置 pgfplots 版本

\begin{document}

\begin{figure}[htbp]
    \centering
    \begin{tikzpicture}
    \begin{axis}[
        width=12cm,
        height=7cm,
        title={\textbf{中国近年出生人口变化趋势 (2019-2023)}},
        title style={font=\large\bfseries},
        xlabel={年份},
        ylabel={出生人口 (万人)},
        xmin=2018.5, xmax=2023.5,
        ymin=800, ymax=1500,
        xtick={2019, 2020, 2021, 2022, 2023},
        ytick={800, 900, 1000, 1100, 1200, 1300, 1400, 1500},
        grid=major,
        grid style={lightgray},
        tick align=outside,
        tick pos=left,
        legend style={at={(0.5, -0.15)}, anchor=north, legend columns=-1},
        nodes near coords,
        nodes near coords align={vertical},
        every node near coord/.append style={font=\tiny, fill=white, inner sep=1pt},
        axis lines=left,
    ]
    % 添加数据点
    \addplot[blue!70!black, thick, mark=*, mark size=2.5pt] coordinates {
        (2019, 1465)
        (2020, 1200)
        (2021, 1062)
        (2022, 956)
        (2023, 902)
    };
    \legend{出生人口}
    \end{axis}
    \end{tikzpicture}
    \caption{2019-2023 年中国出生人口统计数据}
    \label{fig:birth_population}
\end{figure}

\begin{center}
    \small{数据来源：国家统计局《2019-2023 年国民经济和社会发展统计公报》}
\end{center}

\end{document}
```

